def L(narr, sub):
    a, b = narr.split(' / '), sub.split(' / ')
    assert len(a) == len(b), (narr, sub)
    out = []
    for p in b:
        t = re.sub(r' +', ' ', re.sub(r',\s*', ' ', p)).replace('?', '').strip()
        out.append(t if '\n' in t else wrap(t))
    return {"narr": narr, "sub": "|".join(out)}

